sp_widget.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, sans-serif;
  background-color: #f9f9f9;
  color: #333;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: #e82227;
  padding: 10px 20px;
  color: white;
}

.logo {
  display: flex;
  align-items: center;
}

.logo img {
  height: 30px;
  margin-right: 10px;
}

.user-info {
  display: flex;
  align-items: center;
}

.user-icon {
  font-size: 20px;
  margin-right: 5px;
}

.dashboard {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  padding: 20px;
}

.tile {
  position: relative;
  background-color: #002d62;
  color: white;
  text-align: center;
  padding: 20px;
  width: 25rem;
  height: 25rem;
  border-radius: 8px;
  transition: transform 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tile:hover {
  transform: translateY(-5px);
}

.tile .icon {
  font-size: 113px;
  margin-bottom: 10px;
}

.tile p {
  margin-top: 5px;
  font-size: 16px;
}

.notification {
  position: absolute;
  top: -5px;  
  right: -3px;  
  background-color: #ff0000;
  color: white;
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}
 a:focus, button:focus, [role="slider"]:focus, [role="button"]:focus, .btn:focus {
    box-shadow: 0 0 0 0rem #1f3f71 !important; 
    outline: 0rem solid transparent !important; 
}

sp_widget.script:
(function() {
    // Initialize visibility flags for tabs
    data.showAudit = true; // Audit Trail is always visible
    data.showCaseSheet = true; // Case Sheet is always visible
    data.showReports = true; // Reports is always visible
    data.showPendingRequirements = true; // Pending Requirements is always visible
    data.showAssessmentWorkbench = true; // Assessment Workbench default visibility
    data.showGroupOpsWorkbench = true; // Group Ops Workbench default visibility
gs.addErrorMessage(gs.hasRole('admin'))
    // Role-based logic
    if (gs.hasRole('x_rptp_kotak.underwriter')) { 
        data.showGroupOpsWorkbench = false; // Hide Group Ops Workbench for underwriters
    }
    if (gs.hasRole('x_rptp_kotak.groupops')) { 
        data.showAssessmentWorkbench = false; // Hide Assessment Workbench for Group Ops users
    }
    if (gs.hasRole('x_rptp_kotak.netmed')) {
        data.showAssessmentWorkbench = false; // Hide Assessment Workbench for Netmed users
        data.showGroupOpsWorkbench = false;  // Hide Group Ops Workbench for Netmed users
    }

    // Example GlideRecord logic (optional, if needed for dynamic data)
    var gr = new GlideRecord('x_rptp_kotak_requirement_mapping');
    if (data.showPendingRequirements) {
        gr.addQuery('status', 'O');
        gr.query();
        data.rowCount = gr.getRowCount();
    }

    var gr1 = new GlideRecord('x_rptp_kotak_uw_case');
    if (data.showAssessmentWorkbench) {
        gr1.query();
        data.rowCount1 = gr1.getRowCount();
    }
})();
